// Generates templates/composition.json (inline schemas: the portable subset has no $ref).
import { writeFileSync } from 'node:fs';
const out = process.argv[2];

const TS = { type: 'string', minLength: 1, maxLength: 40, description: 'ISO 8601 time with offset (SPEC-E §1 Time)' };
const TSN = { type: ['string', 'null'], maxLength: 40 };
const ID = { type: 'string', minLength: 1, maxLength: 80 };
const ITEMS = { type: 'array', minItems: 1, maxItems: 50, items: { type: 'object', required: ['sku', 'qty'], additionalProperties: false, properties: { sku: ID, qty: { type: 'integer', minimum: 1 } } } };
const EDITION = { type: 'string', minLength: 1, maxLength: 80, description: 'edition id in force at placedAt (R1.3), fixed for the life of the order' };
const RECORDS = { type: 'object', description: 'resume (SPEC-E §3.5): the records and already-received messages of a migrated order that concern this module' };
const AVAIL = { type: 'array', maxItems: 20, items: { type: 'object', required: ['fulfilmentId', 'available'], additionalProperties: false, properties: { fulfilmentId: ID, available: { type: 'boolean' } } } };
const PLAN = { type: 'array', minItems: 1, maxItems: 20, items: { type: 'object', required: ['fulfilmentId', 'location', 'available', 'items', 'amountMinor'], additionalProperties: false, properties: { fulfilmentId: ID, location: { type: ['string', 'null'], maxLength: 40 }, available: { type: 'boolean' }, items: ITEMS, amountMinor: { type: 'integer', minimum: 1 } } } };
const ORDER_STATUSES = ['pending', 'customerActionRequired', 'processing', 'completed', 'failed', 'cancelled', 'timedOut'];
const FULFILMENT_STATUSES = ['unavailable', 'pending', 'processing', 'dispatched', 'completed', 'cancelled', 'failed'];
const ALL_STATUSES = [...new Set([...ORDER_STATUSES, ...FULFILMENT_STATUSES])];
const TEMPLATES = ['action-required', 'order-cancelled', 'order-timed-out', 'fulfilment-failed', 'cancel-refused'];
const obj = (required, properties, description) => ({ type: 'object', required, additionalProperties: false, properties, ...(description ? { description } : {}) });
const nenum = (values) => ({ type: ['string', 'null'], enum: [...values, null] });

const modules = {
  'order-id': {
    file: 'modules/order-id.mjs',
