// Checks templates/composition.json and the skeleton files against COMPOSE.md, and the
// DECOMPOSITION.md checklist for exactly-one ownership. Usage: node check.mjs <root>
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.argv[2];
const tpl = join(root, 'templates');
const errors = [];
const err = (m) => errors.push(m);
const m = JSON.parse(readFileSync(join(tpl, 'composition.json'), 'utf8'));

// api ops and status enums
const api = {};
for (const f of readdirSync(join(root, 'api'))) {
  const s = JSON.parse(readFileSync(join(root, 'api', f), 'utf8'));
  api[s.system] = s;
}
const orderSt = api.orders.tables.orders.fields.status.enum;
const fulSt = api.orders.tables.fulfilments.fields.status.enum;
const TEMPLATES = ['action-required', 'order-cancelled', 'order-timed-out', 'fulfilment-failed', 'cancel-refused', 'unknown-order'];
function kindOk(k) {
  const [sysop, ...rest] = k.split(':');
  const [sys, op] = sysop.split('.');
  if (!api[sys] || !api[sys].ops[op]) return false;
  if (op === 'status') return false;
  if (rest.length === 0) return true;
  if (sysop === 'orders.setStatus') {
    if (rest[0] === 'order') return rest.length === 1 || (rest.length === 2 && orderSt.includes(rest[1]));
    if (rest[0] === 'fulfilment') return rest.length === 1 || (rest.length === 2 && fulSt.includes(rest[1]));
    return false;
  }
  if (sysop === 'notify.send') return rest.length === 1 && TEMPLATES.includes(rest[0]);
  return false;
}

const SUBSET = new Set(['type', 'properties', 'required', 'additionalProperties', 'items', 'enum', 'const', 'minimum', 'maximum', 'minItems', 'maxItems', 'minLength', 'maxLength', 'description']);
const TYPES = new Set(['object', 'array', 'string', 'integer', 'number', 'boolean', 'null']);
function schemaOk(s, path) {
  if (typeof s !== 'object' || s === null || Array.isArray(s)) return err(`${path}: not a schema object`);
  for (const k of Object.keys(s)) if (!SUBSET.has(k)) err(`${path}: keyword ${k} outside the portable subset`);
  if (s.type !== undefined) for (const t of [].concat(s.type)) if (!TYPES.has(t)) err(`${path}: bad type ${t}`);
  if (s.properties) for (const [k, v] of Object.entries(s.properties)) schemaOk(v, `${path}.${k}`);
  if (s.required) for (const r of s.required) if (!s.properties || !(r in s.properties)) err(`${path}: required ${r} not in properties`);
  if (s.items) schemaOk(s.items, `${path}[]`);
  if (typeof s.additionalProperties === 'object') schemaOk(s.additionalProperties, `${path}.*`);
  if (s.enum && s.type) for (const v of s.enum) { const t = v === null ? 'null' : typeof v; if (![].concat(s.type).includes(t)) err(`${path}: enum value ${v} not of type ${s.type}`); }
}

const ID_RE = /^[a-z][a-z0-9-]{0,39}$/;
const FIELDS = ['file', 'purpose', 'rules', 'input', 'output', 'effects', 'humanTasks', 'timers', 'calls', 'reads'];
const ids = Object.keys(m.modules);
if (m.version !== 1) err('version must be 1');
const ruleOwner = {};
for (const id of ids) {
  const mod = m.modules[id];
  if (!ID_RE.test(id)) err(`bad module id ${id}`);
  for (const f of FIELDS) if (!(f in mod)) err(`${id}: missing ${f}`);
  for (const f of Object.keys(mod)) if (!FIELDS.includes(f)) err(`${id}: unknown field ${f}`);
  if (mod.file !== `modules/${id}.mjs`) err(`${id}: file should be modules/${id}.mjs`);
  if (!existsSync(join(tpl, mod.file))) err(`${id}: file missing`);
  for (const k of mod.effects) if (!kindOk(k)) err(`${id}: bad effect kind ${k}`);
  for (const t of mod.humanTasks) if (t !== 'fraudReview') err(`${id}: bad task kind ${t}`);
  if (typeof mod.timers !== 'boolean') err(`${id}: timers must be boolean`);
  for (const c of mod.calls) if (!ids.includes(c)) err(`${id}: calls unknown ${c}`);
  for (const r of mod.reads) if (!api[r]) err(`${id}: reads unknown ${r}`);
  for (const r of mod.rules) {
    if (!/^(R\d\.\d|S\d{1,2})$/.test(r)) err(`${id}: bad rule id ${r}`);
    if (ruleOwner[r]) err(`rule ${r} owned by ${ruleOwner[r]} and ${id}`);
    ruleOwner[r] = id;
  }
  schemaOk(mod.input, `${id}.input`);
  schemaOk(mod.output, `${id}.output`);
}
for (const c of m.parent.calls) if (!ids.includes(c)) err(`parent calls unknown ${c}`);
for (const k of m.parent.effects) if (!kindOk(k)) err(`parent: bad effect ${k}`);
for (const id of ids) if (!m.parent.calls.includes(id) && !ids.some((o) => m.modules[o].calls.includes(id))) err(`${id} is unreachable`);

// acyclic call graph
const state = {};
function visit(id, stack) {
  if (state[id] === 2) return;
  if (state[id] === 1) return err(`cycle: ${[...stack, id].join(' -> ')}`);
  state[id] = 1;
  for (const c of m.modules[id].calls) visit(c, [...stack, id]);
  state[id] = 2;
}
ids.forEach((id) => visit(id, []));

// skeleton files: exports and no module-loading keywords
const parentSrc = readFileSync(join(tpl, 'parent.mjs'), 'utf8');
const pmod = await import(pathToFileURL(join(tpl, 'parent.mjs')));
if (typeof pmod.tick !== 'function') err('parent.mjs: no tick export');
if (/\b(import|require)\b/.test(parentSrc)) err('parent.mjs mentions import/require');
for (const id of ids) {
  const p = join(tpl, m.modules[id].file);
  const src = readFileSync(p, 'utf8');
  if (/\b(import|require)\b/.test(src)) err(`${id}: source mentions import/require`);
  const mod = await import(pathToFileURL(p));
  const needsEvents = m.modules[id].effects.length > 0 || m.modules[id].timers || m.modules[id].humanTasks.length > 0;
  if (typeof mod.step !== 'function') err(`${id}: no step export`);
  if (needsEvents && typeof mod.onEvent !== 'function') err(`${id}: emits but has no onEvent`);
  if (!needsEvents && mod.onEvent) err(`${id}: onEvent exported but nothing can come back`);
  for (const k of Object.keys(mod)) if (!['step', 'onEvent'].includes(k)) err(`${id}: extra export ${k}`);
  // every op of the input enum has a case in the source
  const ops = m.modules[id].input.properties.op?.enum ?? [];
  for (const op of ops) if (!src.includes(`case '${op}'`)) err(`${id}: no case for op ${op}`);
}

// DECOMPOSITION.md checklist: every R / S / § item exactly once
const doc = readFileSync(join(tpl, 'DECOMPOSITION.md'), 'utf8');
const cl = doc.split('\n## ').find((s) => s.startsWith('6.'));
if (!cl) err('no checklist section 6');
const rows = (cl ?? '').split('\n').filter((l) => /^\| (R\d|S\d|§)/.test(l)).map((l) => l.split('|').map((c) => c.trim()));
const seen = {};
for (const r of rows) {
  const item = r[1];
  const owner = r[2].replace(/`/g, '');
  if (seen[item]) err(`checklist item ${item} twice`);
  seen[item] = owner;
  if (owner !== 'parent' && !ids.includes(owner)) err(`checklist ${item}: unknown owner ${owner}`);
  if (/^(R\d\.\d|S\d+)$/.test(item)) {
    if (owner === 'parent' && ruleOwner[item]) err(`${item}: parent in doc but ${ruleOwner[item]} in manifest`);
    if (owner !== 'parent' && ruleOwner[item] !== owner) err(`${item}: ${owner} in doc but ${ruleOwner[item]} in manifest`);
  }
}
const spec = readFileSync(join(root, 'SPEC-E.md'), 'utf8');
const specRules = [...new Set([...spec.matchAll(/^(R\d\.\d) /gm)].map((x) => x[1]))];
const specReadings = [...new Set([...spec.matchAll(/^- (S\d+) /gm)].map((x) => x[1]))];
for (const r of [...specRules, ...specReadings]) if (!seen[r]) err(`checklist misses ${r}`);
for (const r of Object.keys(ruleOwner)) if (!seen[r]) err(`manifest rule ${r} not in checklist`);
const sections = ['§1', '§2', '§3.1', '§3.2', '§3.3', '§3.4', '§3.5', '§4', '§4.8'];
for (const s of sections) if (!Object.keys(seen).some((k) => k === s || k.startsWith(s + ' '))) err(`checklist misses ${s}`);
console.log(`spec rules ${specRules.length}, readings ${specReadings.length}, checklist rows ${rows.length}, modules ${ids.length}`);
console.log(errors.length ? errors.join('\n') : 'OK');
process.exit(errors.length ? 1 : 0);

